meta.css:
:root {
  --bg: #f4f6fb;
  --bg-soft: #eceff7;
  --card: #ffffff;
  --text: #1e2433;
  --text-soft: #5a6478;
  --line: #e3e8f2;
  --primary: #4f46e5;
  --primary-soft: #eef0fe;
  --shadow: 0 1px 3px rgba(30,41,82,.07), 0 4px 14px rgba(30,41,82,.05);
  --note-bg: #fff8e6;
  --note-line: #f0d78a;
  --note-text: #7a5b13;
  --tip-bg: #ecfdf3;
  --tip-line: #a9e5c3;
  --tip-text: #14532d;
  --code-bg: #f6f7fb;
}
html[data-theme="dark"] {
  --bg: #0f1420;
  --bg-soft: #141b2b;
  --card: #171f31;
  --text: #e8ecf5;
  --text-soft: #9aa6bf;
  --line: #263050;
  --primary: #8b8ff7;
  --primary-soft: #232a4a;
  --shadow: 0 1px 3px rgba(0,0,0,.3), 0 4px 16px rgba(0,0,0,.25);
  --note-bg: #2a2410;
  --note-line: #6b5a1e;
  --note-text: #e8d48a;
  --tip-bg: #10281c;
  --tip-line: #1f5c3a;
  --tip-text: #8fe0b0;
  --code-bg: #1a2236;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.75;
  transition: background .25s, color .25s;
}
/* ============ 顶栏 ============ */
.topbar {
  position: fixed; top: 0; left: 0; right: 0; height: 60px; z-index: 100;
  background: color-mix(in srgb, var(--card) 88%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
  display: flex; align-items: center; gap: 16px;
  padding: 0 22px;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 16px; white-space: nowrap; }
.brand .logo {
  width: 30px; height: 30px; border-radius: 8px; flex: none;
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  display: grid; place-items: center; color: #fff; font-size: 15px; font-weight: 800;
}
.brand small { color: var(--text-soft); font-weight: 500; font-size: 12px; }
.searchbox { flex: 1; max-width: 560px; margin: 0 auto; position: relative; }
.searchbox input {
  width: 100%; height: 38px; border-radius: 10px;
  border: 1px solid var(--line); background: var(--code-bg); color: var(--text);
  padding: 0 40px 0 38px; font-size: 14px; outline: none;
  transition: border-color .2s, box-shadow .2s;
}
.searchbox input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-soft); }
.searchbox .icon { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); color: var(--text-soft); font-size: 14px; }
.searchbox kbd {
  position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
  font-size: 11px; color: var(--text-soft); border: 1px solid var(--line);
  border-radius: 5px; padding: 1px 6px; background: var(--card); font-family: inherit;
}
.searchbox .clear-btn {
  position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
  border: none; background: var(--line); color: var(--text); width: 20px; height: 20px;
  border-radius: 50%; cursor: pointer; display: none; align-items: center; justify-content: center; font-size: 12px;
}
.icon-btn {
  width: 36px; height: 36px; border-radius: 9px; border: 1px solid var(--line);
  background: var(--card); color: var(--text); cursor: pointer; font-size: 16px;
  display: grid; place-items: center; flex: none;
}
.icon-btn:hover { border-color: var(--primary); color: var(--primary); }
/* ============ 侧边栏 ============ */
.sidebar {
  position: fixed; top: 60px; left: 0; bottom: 0; width: 264px; z-index: 90;
  background: var(--card); border-right: 1px solid var(--line);
  overflow-y: auto; padding: 18px 12px 40px;
  transition: transform .25s;
}
.sidebar::-webkit-scrollbar { width: 5px; }
.sidebar::-webkit-scrollbar-thumb { background: var(--line); border-radius: 3px; }
.toc-group { margin-bottom: 6px; }
.toc-ch {
  display: flex; align-items: center; gap: 8px;
  padding: 7px 10px; border-radius: 8px; cursor: pointer;
  font-size: 13.5px; font-weight: 600; color: var(--text);
  user-select: none;
}
.toc-ch:hover { background: var(--bg-soft); }
.toc-ch .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.toc-ch .arrow { margin-left: auto; font-size: 10px; color: var(--text-soft); transition: transform .2s; }
.toc-group.open .toc-ch .arrow { transform: rotate(90deg); }
.toc-items { display: none; padding: 2px 0 6px 26px; }
.toc-group.open .toc-items { display: block; }
.toc-items a {
  display: block; padding: 4px 10px; font-size: 12.5px; color: var(--text-soft);
  text-decoration: none; border-radius: 6px; border-left: 2px solid transparent;
}
.toc-items a:hover { color: var(--primary); background: var(--primary-soft); }
.toc-items a.active { color: var(--primary); border-left-color: var(--primary); background: var(--primary-soft); font-weight: 600; }
/* ============ 主区域 ============ */
.main { margin: 60px 0 0 264px; padding: 34px 40px 120px; max-width: 1080px; }
@media (max-width: 960px) {
  .sidebar { transform: translateX(-100%); }
  .sidebar.open { transform: translateX(0); }
  .main { margin-left: 0; padding: 24px 18px 100px; }
  .menu-btn { display: grid !important; }
}
.menu-btn { display: none; }
/* ============ 封面 ============ */
.hero {
  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 55%, #a21caf 100%);
  border-radius: 20px; padding: 44px 42px; color: #fff; margin-bottom: 34px;
  position: relative; overflow: hidden;
}
.hero::after {
  content: "∫ ∑ ∮ √ π ∞"; position: absolute; right: 18px; bottom: -12px;
  font-size: 88px; opacity: .13; font-family: Georgia, serif; white-space: nowrap;
}
.hero h1 { font-size: 30px; letter-spacing: 1px; margin-bottom: 10px; }
.hero p { font-size: 14px; opacity: .92; max-width: 640px; }
.hero .stats { display: flex; gap: 26px; margin-top: 22px; flex-wrap: wrap; }
.hero .stat b { font-size: 22px; display: block; }
.hero .stat span { font-size: 12px; opacity: .85; }
.usage {
  background: var(--card); border: 1px solid var(--line); border-radius: 14px;
  padding: 16px 20px; margin-bottom: 34px; font-size: 13px; color: var(--text-soft);
  display: flex; gap: 10px; align-items: flex-start; box-shadow: var(--shadow);
}
.usage b { color: var(--text); }
/* ============ 章节 ============ */
.chapter { margin-bottom: 52px; }
.ch-head {
  display: flex; align-items: center; gap: 16px; margin-bottom: 8px;
  padding: 20px 24px; border-radius: 16px; color: #fff;
  background: linear-gradient(135deg, var(--c1), var(--c2));
  box-shadow: var(--shadow);
}
.ch-head .num {
  font-size: 13px; font-weight: 800; letter-spacing: 1px;
  background: rgba(255,255,255,.22); border-radius: 9px; padding: 6px 12px; white-space: nowrap;
}
.ch-head h2 { font-size: 21px; letter-spacing: .5px; }
.ch-head .desc { font-size: 12.5px; opacity: .92; margin-top: 2px; }
.ch-src {
  display: inline-block; font-size: 11.5px; color: var(--text-soft);
  background: var(--bg-soft); border: 1px solid var(--line);
  padding: 3px 12px; border-radius: 99px; margin: 4px 0 18px 4px;
}
.sec { margin-bottom: 30px; }
.sec > h3 {
  font-size: 17px; margin-bottom: 14px; padding-left: 12px;
  border-left: 4px solid var(--primary); line-height: 1.4;
}
.sec > h3 .en { font-size: 12px; color: var(--text-soft); font-weight: 500; margin-left: 8px; }
/* ============ 公式卡片 ============ */
.card {
  background: var(--card); border: 1px solid var(--line); border-radius: 13px;
  padding: 16px 20px; margin-bottom: 13px; box-shadow: var(--shadow);
  border-left: 4px solid var(--primary);
  break-inside: avoid;
}
.card .ct {
  font-size: 14px; font-weight: 700; margin-bottom: 7px; display: flex; align-items: center; gap: 8px;
}
.card .ct .tag {
  font-size: 10.5px; font-weight: 600; color: var(--primary);
  background: var(--primary-soft); border-radius: 5px; padding: 1px 7px; letter-spacing: .3px;
}
.card .body { font-size: 14px; }
.card ul { padding-left: 20px; }
.card li { margin: 3px 0; }
.card li::marker { color: var(--primary); }
.formula {
  background: var(--code-bg); border: 1px solid var(--line); border-radius: 9px;
  padding: 12px 16px; margin: 9px 0; overflow-x: auto; font-size: 15.5px;
}
.note, .tip {
  border-radius: 9px; padding: 9px 14px; font-size: 13px; margin-top: 9px;
  border: 1px solid; line-height: 1.7;
}
.note { background: var(--note-bg); border-color: var(--note-line); color: var(--note-text); }
.tip { background: var(--tip-bg); border-color: var(--tip-line); color: var(--tip-text); }
.note::before { content: "注 "; font-weight: 700; }
.tip::before { content: "技巧 "; font-weight: 700; }
.note.nolabel::before, .tip.nolabel::before { content: none; }
/* 表格 */
.tbl { width: 100%; border-collapse: collapse; margin: 10px 0; font-size: 13.5px; }
.tbl th, .tbl td { border: 1px solid var(--line); padding: 7px 12px; text-align: left; vertical-align: top; }
.tbl th { background: var(--primary-soft); color: var(--primary); font-weight: 700; white-space: nowrap; }
.tbl tr:nth-child(even) td { background: var(--code-bg); }
/* 高亮 */
mark { background: #fde68a; color: inherit; border-radius: 3px; padding: 0 2px; }
html[data-theme="dark"] mark { background: #7a6410; }
.hidden { display: none !important; }
.no-result {
  text-align: center; padding: 60px 20px; color: var(--text-soft); font-size: 14px; display: none;
}
.no-result.show { display: block; }
.search-info {
  font-size: 12.5px; color: var(--text-soft); margin-bottom: 18px; display: none;
}
.search-info.show { display: block; }
/* 页脚 */
.footer {
  margin-top: 60px; padding-top: 22px; border-top: 1px solid var(--line);
  font-size: 12px; color: var(--text-soft); text-align: center; line-height: 2;
}
/* 返回顶部 */
.backtop {
  position: fixed; right: 26px; bottom: 30px; width: 42px; height: 42px;
  border-radius: 50%; border: none; background: var(--primary); color: #fff;
  font-size: 18px; cursor: pointer; box-shadow: 0 4px 16px rgba(79,70,229,.4);
  display: none; place-items: center; z-index: 95;
}
.backtop.show { display: grid; }
/* 关系图 */
.rel { display: flex; flex-wrap: wrap; gap: 8px 26px; align-items: center; padding: 14px 16px; background: var(--code-bg); border: 1px solid var(--line); border-radius: 10px; margin: 10px 0; font-size: 14px; font-weight: 600; }
.rel .node { background: var(--card); border: 1.5px solid var(--primary); color: var(--primary); border-radius: 8px; padding: 3px 12px; white-space: nowrap; }
.rel .arr { color: var(--text-soft); font-weight: 400; white-space: nowrap; }
/* 打印 */
@media print {
  .topbar, .sidebar, .backtop, .usage, .no-result { display: none !important; }
  .main { margin: 0; max-width: 100%; padding: 0; }
  body { background: #fff; }
  .card, .ch-head { box-shadow: none; break-inside: avoid; }
  .hero { background: #4f46e5 !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
